// TrackFields are the fields of a [Track], to write.
type TrackFields struct {
	Id     uint32
	Origin Vec2
	Frame  FrameFields
	Points []float32
	Name   string
}

// MarshalBinary writes a [Track] with every field. It fails with a
// [*tafla.BuildError] if it's longer than its offset type, uint32, addresses.
func (f TrackFields) MarshalBinary() ([]byte, error) {
	return f.AppendBinary(nil)
}

// AppendBinary appends a [Track] with every field to bytes, as
// [TrackFields.MarshalBinary] writes it, and returns the extended bytes, into
// their capacity when they have room. It fails as MarshalBinary does.
func (f TrackFields) AppendBinary(bytes []byte) ([]byte, error) {
	sizer, err := tafla.NewTableSizer(5, Track{}.layout())
	if err != nil {
		return nil, err
	}
	sizer.AddFields(3, 50)
	sizer.AddFloat32Array(len(f.Points))
	sizer.AddString(f.Name)

	writer, err := sizer.AppendWriter(bytes)
	if err != nil {
		return nil, err
	}
	fixed := writer.ReserveFields(50)
	_ = fixed[69]
	binary.LittleEndian.PutUint32(fixed, 20)
	binary.LittleEndian.PutUint32(fixed[4:], 24)
	binary.LittleEndian.PutUint32(fixed[8:], 32)
	binary.LittleEndian.PutUint32(fixed[20:], f.Id)
	f.Origin.put(fixed[24:])
	f.Frame.put(fixed[32:])
	writer.SetFloat32Array(3, f.Points)
	writer.SetString(4, f.Name)

	return writer.Bytes()
}

